export function solve(code: string): boolean {
  if (typeof code !== 'string' || code.length !== 16) return false;
  const s = code.toUpperCase();

  // Positions (0-based) that hold a digit or its letter stand-in
  const digitPos = new Set([6, 7, 9, 10, 12, 13, 14]);
  const letterDigits = 'LMNPQRSTUV';

  // Normalize: digit-positions become '0'-'9'; all other characters are kept as-is
  let n = '';
  for (let i = 0; i < 16; i++) {
    const c = s[i];
    if (digitPos.has(i)) {
      if (c >= '0' && c <= '9') {
        n += c;
      } else {
        const idx = letterDigits.indexOf(c);
        if (idx < 0) return false;
        n += String(idx);
      }
    } else {
      n += c;
    }
  }

  const isLetter = (c: string): boolean => c >= 'A' && c <= 'Z';
  const isVowel = (c: string): boolean => 'AEIOU'.indexOf(c) >= 0;

  // Name code: consonants, then vowels, then X padding
  const validName = (part: string): boolean => {
    let state = 0; // 0 = consonants, 1 = vowels, 2 = X padding
    for (const ch of part) {
      if (!isLetter(ch)) return false;
      if (state === 2) {
        if (ch !== 'X') return false;
        continue;
      }
      if (isVowel(ch)) {
        state = 1;
      } else if (ch === 'X') {
        state = 2;
      } else {
        // consonant
        if (state === 1) return false;
      }
    }
    return true;
  };

  if (!validName(n.slice(0, 3))) return false;
  if (!validName(n.slice(3, 6))) return false;

  // Year (two digits)
  const yy = Number(n[6]) * 10 + Number(n[7]);

  // Month letter
  const months = 'ABCDEHLMPRST';
  const month = months.indexOf(n[8]) + 1;
  if (month === 0) return false;

  // Day (male 1-31, female 41-71)
  const rawDay = Number(n.slice(9, 11));
  let day: number;
  if (rawDay >= 1 && rawDay <= 31) {
    day = rawDay;
  } else if (rawDay >= 41 && rawDay <= 71) {
    day = rawDay - 40;
  } else {
    return false;
  }

  // Validate the date exists
  let maxDay: number;
  if (month === 2) {
    maxDay = yy % 4 === 0 ? 29 : 28;
  } else if (month === 4 || month === 6 || month === 9 || month === 11) {
    maxDay = 30;
  } else {
    maxDay = 31;
  }
  if (day < 1 || day > maxDay) return false;

  // Place of birth: letter then three digit-positions
  if ('ABCDEFGHILMZ'.indexOf(n[11]) < 0) return false;

  // Check letter must be a letter
  if (!isLetter(n[15])) return false;

  // Check character computation
  const oddVals = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23];
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const ch = n[i];
    const isDigit = ch >= '0' && ch <= '9';
    if (i % 2 === 0) {
      // odd position (1st, 3rd, ...)
      if (isDigit) {
        sum += oddVals[ch.charCodeAt(0) - 48];
      } else {
        sum += oddVals[ch.charCodeAt(0) - 65];
      }
    } else {
      // even position (2nd, 4th, ...)
      if (isDigit) {
        sum += ch.charCodeAt(0) - 48;
      } else {
        sum += ch.charCodeAt(0) - 65;
      }
    }
  }

  const expected = String.fromCharCode(65 + (sum % 26));
  return expected === n[15];
}

const rePropName =
  /[^.[\]]+|\[(?:(-?\d+(?:\.\d+)?)|(["'])((?:(?!\2)[^\\]|\\.)*?)\2)\]|(?=(?:\.|\[\])(?:\.|\[\]|$))/g;
const reEscapeChar = /\\(\\)?/g;
const reIsDeepProp = /\.|\[(?:[^[\]]*|(["'])(?:(?!\1)[^\\]|\\.)*?\1)\]/;
const reIsPlainProp = /^\w*$/;

function stringToPath(s: string): string[] {
  const result: string[] = [];
  if (s.charCodeAt(0) === 46) {
    result.push("");
  }
  s.replace(
    rePropName,
    (
      match: string,
      number: string | undefined,
      quote: string | undefined,
      sub: string | undefined
    ): string => {
      result.push(
        quote ? (sub ?? "").replace(reEscapeChar, "$1") : (number || match)
      );
      return "";
    }
  );
  return result;
}

function isKey(value: string, object: unknown): boolean {
  return (
    reIsPlainProp.test(value) ||
    !reIsDeepProp.test(value) ||
    (object != null && value in Object(object))
  );
}

export function solve(obj: unknown, path: string): unknown {
  const keys: string[] = isKey(path, obj) ? [path] : stringToPath(path);
  let cur: any = obj;
  let i = 0;
  while (cur != null && i < keys.length) {
    cur = cur[keys[i++]];
  }
  return i > 0 && i === keys.length ? cur : undefined;
}

export function solve(range: string): string | null {
  return lib.validRange(range);
}

export function solve(versions: string[], range: string): string | null {
  return lib.minSatisfying(versions, range);
}

export function solve(version: string, range: string): boolean {
  return Boolean(lib.ltr(version, range));
}

export function solve(obj: unknown, path: string): unknown {
  return lib.get(obj, path);
}

export function solve(code: string): boolean {
  if (typeof code !== 'string') return false;
  const s = code.toUpperCase();
  if (s.length !== 16 || !/^[A-Z0-9]{16}$/.test(s)) return false;

  // Format and algorithmic check from the library (it-IT locale)
  if (!lib.isTaxID(s, 'it-IT')) return false;

  // Surname and given name: consonants, then vowels, then X padding
  const isVowel = (c: string): boolean => 'AEIOU'.indexOf(c) >= 0;
  const checkName = (part: string): boolean => {
    let state = 0; // 0 = consonants, 1 = vowels, 2 = X padding
    for (const c of part) {
      if (state === 0) {
        if (c === 'X') state = 2;
        else if (isVowel(c)) state = 1;
      } else if (state === 1) {
        if (c === 'X') state = 2;
        else if (!isVowel(c)) return false;
      } else {
        if (c !== 'X') return false;
      }
    }
    return true;
  };
  if (!checkName(s.slice(0, 3)) || !checkName(s.slice(3, 6))) return false;

  // Normalize omocodia letters in digit positions to digits
  const digitPositions = [6, 7, 9, 10, 12, 13, 14];
  const n: string[] = s.split('');
  for (const i of digitPositions) {
    const c = s[i];
    if (c >= '0' && c <= '9') {
      n[i] = c;
    } else {
      const idx = 'LMNPQRSTUV'.indexOf(c);
      if (idx < 0) return false;
      n[i] = String(idx);
    }
  }

  // Month
  const mi = 'ABCDEHLMPRST'.indexOf(s[8]);
  if (mi < 0) return false;
  const month = mi + 1;

  // Day (women: +40)
  let day = parseInt(n[9] + n[10], 10);
  if (day >= 41 && day <= 71) day -= 40;
  if (day < 1 || day > 31) return false;

  // Year and leap year (two-digit year divisible by 4, 00 included)
  const yy = parseInt(n[6] + n[7], 10);
  const leap = yy % 4 === 0;
  let maxDay: number;
  if (month === 2) maxDay = leap ? 29 : 28;
  else if (month === 4 || month === 6 || month === 9 || month === 11) maxDay = 30;
  else maxDay = 31;
  if (day > maxDay) return false;

  // Place of birth initial letter
  if ('ABCDEFGHILMZ'.indexOf(s[11]) < 0) return false;

  // Check letter
  const ODD = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23];
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = n[i];
    const v = c >= '0' && c <= '9' ? c.charCodeAt(0) - 48 : c.charCodeAt(0) - 65;
    if (i % 2 === 0) sum += ODD[v];
    else sum += v;
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  return expected === s[15];
}

export function solve(code: string): boolean {
  if (typeof code !== "string" || code.length !== 16) return false;
  const s = code.toUpperCase();

  const DIGIT_LETTERS = "LMNPQRSTUV";
  const isLetter = (c: string): boolean => c >= "A" && c <= "Z";
  const isVowel = (c: string): boolean => "AEIOU".indexOf(c) !== -1;

  // Value of a digit or digit-standing letter (L..V), or -1 if neither.
  const digitOf = (c: string): number => {
    if (c >= "0" && c <= "9") return c.charCodeAt(0) - 48;
    return DIGIT_LETTERS.indexOf(c);
  };

  // Name code: consonants, then vowels, then X padding.
  // State 0 = consonant phase, 1 = vowel phase, 2 = X padding phase.
  const nameOk = (part: string): boolean => {
    let state = 0;
    for (const ch of part) {
      if (!isLetter(ch)) return false;
      if (state === 2) {
        if (ch !== "X") return false;
        continue;
      }
      if (state === 0) {
        if (ch === "X") state = 2;
        else if (isVowel(ch)) state = 1;
        // otherwise a consonant: stay in state 0
      } else {
        // state 1
        if (isVowel(ch)) continue;
        if (ch === "X") state = 2;
        else return false;
      }
    }
    return true;
  };

  // Surname and given name
  if (!nameOk(s.slice(0, 3))) return false;
  if (!nameOk(s.slice(3, 6))) return false;

  // Year (positions 6-7)
  const y1 = digitOf(s[6]);
  const y2 = digitOf(s[7]);
  if (y1 < 0 || y2 < 0) return false;
  const yy = y1 * 10 + y2;

  // Month (position 8)
  const monthIdx = "ABCDEHLMPRST".indexOf(s[8]);
  if (monthIdx === -1) return false;
  const month = monthIdx + 1;

  // Day (positions 9-10)
  const d1 = digitOf(s[9]);
  const d2 = digitOf(s[10]);
  if (d1 < 0 || d2 < 0) return false;
  let day = d1 * 10 + d2;
  if (day >= 41 && day <= 71) {
    day -= 40;
  } else if (day < 1 || day > 31) {
    return false;
  }

  // Validate day within month, with leap years for February
  const leap = yy % 4 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > daysInMonth[month - 1]) return false;

  // Place of birth (position 11 letter, 12-14 digits)
  if ("ABCDEFGHILMZ".indexOf(s[11]) === -1) return false;
  for (const i of [12, 13, 14]) {
    if (digitOf(s[i]) < 0) return false;
  }

  // Check letter: normalize digit positions to digit characters
  const digitPositions = new Set([6, 7, 9, 10, 12, 13, 14]);
  const norm: string[] = [];
  for (let i = 0; i < 15; i++) {
    if (digitPositions.has(i)) {
      norm.push(String(digitOf(s[i])));
    } else {
      norm.push(s[i]);
    }
  }

  const ODD_TABLE = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8,
    12, 14, 16, 10, 22, 25, 24, 23];

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = norm[i];
    // Index into A..Z (0..25); digits 0..9 coincide with A..J values.
    const idx = c >= "0" && c <= "9" ? c.charCodeAt(0) - 48 : c.charCodeAt(0) - 65;
    if (i % 2 === 0) {
      // 1st, 3rd, ... character (odd position)
      sum += ODD_TABLE[idx];
    } else {
      // 2nd, 4th, ... character (even position)
      sum += idx;
    }
  }

  const expected = String.fromCharCode(65 + (sum % 26));
  return s[15] === expected;
}

