const RE_PROP_NAME =
  /[^.[\]]+|\[(?:(-?\d+(?:\.\d+)?)|(["'])((?:(?!\2)[^\\]|\\.)*?)\2)\]|(?=(?:\.|\[\])(?:\.|\[\]|$))/g;
const RE_ESCAPE_CHAR = /\\(\\)?/g;
const RE_IS_PLAIN_PROP = /^\w*$/;
const RE_IS_DEEP_PROP = /\.|\[(?:[^[\]]*|(["'])(?:(?!\1)[^\\]|\\.)*?\1)\]/;

function stringToPath(s: string): string[] {
  const result: string[] = [];
  if (s.charCodeAt(0) === 46 /* '.' */) {
    result.push("");
  }
  s.replace(
    RE_PROP_NAME,
    (match: string, num?: string, quote?: string, sub?: string): string => {
      result.push(
        quote ? (sub ?? "").replace(RE_ESCAPE_CHAR, "$1") : (num || match)
      );
      return match;
    }
  );
  return result;
}

function isKey(value: string, obj: unknown): boolean {
  if (RE_IS_PLAIN_PROP.test(value) || !RE_IS_DEEP_PROP.test(value)) {
    return true;
  }
  return obj != null && value in Object(obj);
}

export function solve(obj: unknown, path: string): unknown {
  const keys: string[] = isKey(path, obj) ? [path] : stringToPath(path);
  let cur: any = obj;
  let i = 0;
  while (cur != null && i < keys.length) {
    cur = cur[keys[i++]];
  }
  return i > 0 && i === keys.length ? cur : undefined;
}

export function solve(versions: string[], range: string): string | null {
