type Ver = { major: number; minor: number; patch: number; pre: string[] };
type Cmp = { op: string; ver: Ver };
type Part = { M?: string; m?: string; p?: string; pre: string[] };

const NUM = "0|[1-9]\\d*";
const PRE_ID = "0|[1-9]\\d*|\\d*[A-Za-z-][0-9A-Za-z-]*";
const PRE = `(?:${PRE_ID})(?:\\.(?:${PRE_ID}))*`;
const BUILD = "[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*";
const XR = "0|[1-9]\\d*|[xX*]";

const FULL_RE = new RegExp(`^v?(${NUM})\\.(${NUM})\\.(${NUM})(?:-(${PRE}))?(?:\\+(${BUILD}))?$`);
const PART_RE = new RegExp(
  `^(${XR})(?:\\.(${XR})(?:\\.(${XR})(?:-(${PRE}))?(?:\\+(${BUILD}))?)?)?$`
);
const COMP_RE = /^(<=|>=|<|>|=|~>?|\^)?(.*)$/;

const ZERO_PRE = ["0"];

function c(op: string, major: number, minor: number, patch: number, pre: string[] = []): Cmp {
  return { op, ver: { major, minor, patch, pre } };
}

const ANY: Cmp = c(">=", 0, 0, 0);

function isX(s: string | undefined): boolean {
  return s === undefined || /^[xX*]$/.test(s);
}

function parsePart(s: string): Part {
  const m = PART_RE.exec(s.replace(/^[v=]+/, ""));
  if (!m) throw new Error("invalid comparator");
  return { M: m[1], m: m[2], p: m[3], pre: m[4] ? m[4].split(".") : [] };
}

function expandOp(op0: string, part: Part): Cmp[] {
  const op = op0 === "~>" ? "~" : op0;
  const xM = isX(part.M);
  const xm = xM || isX(part.m);
  const xp = xm || isX(part.p);
  const M = xM ? 0 : Number(part.M);
  const m = xm ? 0 : Number(part.m);
  const p = xp ? 0 : Number(part.p);
  const pre = part.pre;

  switch (op) {
    case "":
    case "=":
      if (xM) return [ANY];
      if (xm) return [c(">=", M, 0, 0), c("<", M + 1, 0, 0, ZERO_PRE)];
      if (xp) return [c(">=", M, m, 0), c("<", M, m + 1, 0, ZERO_PRE)];
      return [c("=", M, m, p, pre)];

    case ">":
      if (xM) return [c("<", 0, 0, 0, ZERO_PRE)];
      if (xm) return [c(">=", M + 1, 0, 0)];
      if (xp) return [c(">=", M, m + 1, 0)];
      return [c(">", M, m, p, pre)];

    case ">=":
      if (xM) return [ANY];
      if (xm) return [c(">=", M, 0, 0)];
      if (xp) return [c(">=", M, m, 0)];
      return [c(">=", M, m, p, pre)];

    case "<":
      if (xM) return [c("<", 0, 0, 0, ZERO_PRE)];
      if (xm) return [c("<", M, 0, 0, ZERO_PRE)];
      if (xp) return [c("<", M, m, 0, ZERO_PRE)];
      return [c("<", M, m, p, pre)];

    case "<=":
      if (xM) return [ANY];
      if (xm) return [c("<", M + 1, 0, 0, ZERO_PRE)];
      if (xp) return [c("<", M, m + 1, 0, ZERO_PRE)];
      return [c("<=", M, m, p, pre)];

    case "~":
      if (xM) return [ANY];
      if (xm) return [c(">=", M, 0, 0), c("<", M + 1, 0, 0, ZERO_PRE)];
      if (xp) return [c(">=", M, m, 0), c("<", M, m + 1, 0, ZERO_PRE)];
      return [c(">=", M, m, p, pre), c("<", M, m + 1, 0, ZERO_PRE)];

    case "^":
      if (xM) return [ANY];
      if (xm) return [c(">=", M, 0, 0), c("<", M + 1, 0, 0, ZERO_PRE)];
      if (xp) {
        if (M === 0) return [c(">=", 0, m, 0), c("<", 0, m + 1, 0, ZERO_PRE)];
        return [c(">=", M, m, 0), c("<", M + 1, 0, 0, ZERO_PRE)];
      }
      if (M === 0) {
        if (m === 0) return [c(">=", 0, 0, p, pre), c("<", 0, 0, p + 1, ZERO_PRE)];
        return [c(">=", 0, m, p, pre), c("<", 0, m + 1, 0, ZERO_PRE)];
      }
      return [c(">=", M, m, p, pre), c("<", M + 1, 0, 0, ZERO_PRE)];

    default:
      throw new Error("unknown operator");
  }
}

function expandHyphen(a: Part, b: Part): Cmp[] {
  const out: Cmp[] = [];
  if (!isX(a.M)) {
    const M = Number(a.M);
    if (isX(a.m)) out.push(c(">=", M, 0, 0));
    else if (isX(a.p)) out.push(c(">=", M, Number(a.m), 0));
    else out.push(c(">=", M, Number(a.m), Number(a.p), a.pre));
  }
  if (!isX(b.M)) {
    const M = Number(b.M);
    if (isX(b.m)) out.push(c("<", M + 1, 0, 0, ZERO_PRE));
    else if (isX(b.p)) out.push(c("<", M, Number(b.m) + 1, 0, ZERO_PRE));
    else out.push(c("<=", M, Number(b.m), Number(b.p), b.pre));
  }
  return out.length ? out : [ANY];
}

function expandToken(t: string): Cmp[] {
  const m = COMP_RE.exec(t);
  if (!m) throw new Error("invalid comparator");
  const part = parsePart(m[2]);
  return expandOp(m[1] ?? "", part);
}

function parseSet(s: string): Cmp[] {
  if (s === "") return [ANY];
  const norm = s.replace(/(<=|>=|<|>|=|~>|~|\^)\s+/g, "$1");
  const toks = norm.split(/\s+/);
  if (toks.length === 3 && toks[1] === "-") {
    return expandHyphen(parsePart(toks[0]), parsePart(toks[2]));
  }
  const out: Cmp[] = [];
  for (const t of toks) out.push(...expandToken(t));
  return out;
}

function parseRange(range: string): Cmp[][] {
  return range.split("||").map((part) => parseSet(part.trim()));
}

function parseVersion(s: string): Ver | null {
  const m = FULL_RE.exec(s.trim());
  if (!m) return null;
  return {
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    pre: m[4] ? m[4].split(".") : [],
  };
}

function cmpIdent(a: string, b: string): number {
  const an = /^\d+$/.test(a);
  const bn = /^\d+$/.test(b);
  if (an && bn) {
    const x = Number(a);
    const y = Number(b);
    return x < y ? -1 : x > y ? 1 : 0;
  }
  if (an) return -1;
  if (bn) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function cmpPre(a: string[], b: string[]): number {
  if (a.length === 0 && b.length === 0) return 0;
  if (a.length === 0) return 1;
  if (b.length === 0) return -1;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const r = cmpIdent(a[i], b[i]);
    if (r !== 0) return r;
  }
  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
}

function cmpVer(a: Ver, b: Ver): number {
  if (a.major !== b.major) return a.major < b.major ? -1 : 1;
  if (a.minor !== b.minor) return a.minor < b.minor ? -1 : 1;
  if (a.patch !== b.patch) return a.patch < b.patch ? -1 : 1;
  return cmpPre(a.pre, b.pre);
}

function testCmp(v: Ver, cm: Cmp): boolean {
  const r = cmpVer(v, cm.ver);
  switch (cm.op) {
    case "=": return r === 0;
    case "<": return r < 0;
    case "<=": return r <= 0;
    case ">": return r > 0;
    case ">=": return r >= 0;
    default: return false;
  }
}

function testSet(set: Cmp[], v: Ver): boolean {
  if (!set.every((cm) => testCmp(v, cm))) return false;
  if (v.pre.length === 0) return true;
  return set.some(
    (cm) =>
      cm.ver.pre.length > 0 &&
      cm.ver.major === v.major &&
      cm.ver.minor === v.minor &&
      cm.ver.patch === v.patch
  );
}

export function solve(versions: string[], range: string): string | null {
  let sets: Cmp[][];
  try {
    sets = parseRange(range);
  } catch {
    return null;
  }

  let best: string | null = null;
  let bestVer: Ver | null = null;

  for (const s of versions) {
    const v = parseVersion(s);
    if (!v) continue;
    if (!sets.some((set) => testSet(set, v))) continue;
    if (bestVer === null || cmpVer(v, bestVer) < 0) {
      best = s;
      bestVer = v;
    }
  }

  return best;
}

export function solve(code: string): boolean {
  if (typeof code !== 'string' || code.length !== 16) return false;
  const s = code.toUpperCase();
  if (!/^[A-Z0-9]{16}$/.test(s)) return false;

  const isLetter = (c: string): boolean => c >= 'A' && c <= 'Z';
  const OMO = 'LMNPQRSTUV';
  const DIGIT_POS = [6, 7, 9, 10, 12, 13, 14];

  // Name positions must be letters.
  for (let i = 0; i < 6; i++) {
    if (!isLetter(s[i])) return false;
  }

  // Name rule: consonants, then vowels, then X padding (nothing after an X but X).
  const nameOk = (part: string): boolean => /^[^AEIOUX]*[AEIOU]*X*$/.test(part);
  if (!nameOk(s.slice(0, 3)) || !nameOk(s.slice(3, 6))) return false;

  // Normalise digit positions (digits or omocodia letters) into plain digits.
