  const chars: string[] = code.toUpperCase().split('');
  const VOWELS = 'AEIOU';
  const OMOCODIA = 'LMNPQRSTUV';
  const DIGIT_POS = [6, 7, 9, 10, 12, 13, 14];

  // Every character must be an ASCII letter or digit
  for (const c of chars) {
    if (!/^[A-Z0-9]$/.test(c)) return false;
  }

  // Name codes: consonants, then vowels, then X padding
  const checkName = (start: number): boolean => {
    let state = 0; // 0 = consonants, 1 = vowels seen, 2 = X padding seen
    for (let i = start; i < start + 3; i++) {
      const c = chars[i];
      if (c < 'A' || c > 'Z') return false;
      if (state === 2) {
        if (c !== 'X') return false;
        continue;
      }
      if (c === 'X') {
        state = 2;
        continue;
      }
      if (VOWELS.includes(c)) {
        state = 1;
        continue;
      }
      // consonant
      if (state === 1) return false;
    }
    return true;
  };

  if (!checkName(0) || !checkName(3)) return false;

  // Digit positions: digits or omocodia letters (L=0 ... V=9)
  for (const i of DIGIT_POS) {
    const c = chars[i];
    if (OMOCODIA.includes(c)) {
      chars[i] = String(OMOCODIA.indexOf(c));
    } else if (!/^[0-9]$/.test(c)) {
      return false;
    }
  }

  // Year (any two digits; used for leap-year test)
  const year = parseInt(chars[6] + chars[7], 10);

  // Month letter
  const MONTHS = 'ABCDEHLMPRST';
  const monthIdx = MONTHS.indexOf(chars[8]);
  if (monthIdx < 0) return false;
  const month = monthIdx + 1;

  // Day (women: +40)
  let day = parseInt(chars[9] + chars[10], 10);
  if (day >= 41 && day <= 71) {
    day -= 40;
  } else if (day < 1 || day > 31) {
    return false;
  }

  const isLeap = year % 4 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > daysInMonth[month - 1]) return false;

  // Place of birth: letter among A-I, L, M, Z
  if (!/^[A-IL-MZ]$/.test(chars[11])) return false;

  // Check character
  const ODD_DIGITS = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];
  const ODD_LETTERS = [
    1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11,
    3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23
  ];

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = chars[i];
    const isDigit = /^[0-9]$/.test(c);
    if (i % 2 === 0) {
      // 1st, 3rd, ... 15th characters (odd positions)
      sum += isDigit ? ODD_DIGITS[+c] : ODD_LETTERS[c.charCodeAt(0) - 65];
    } else {
      // 2nd, 4th, ... 14th characters (even positions)
      sum += isDigit ? +c : c.charCodeAt(0) - 65;
    }
  }

  const expected = String.fromCharCode(65 + (sum % 26));
  return chars[15] === expected;
