// Lodash-compatible path parsing regexes
const reIsDeepProp = /\.|\[(?:[^[\]]*|(["'])(?:(?!\1)[^\\]|\\.)*?\1)\]/;
const reIsPlainProp = /^\w*$/;
const rePropName =
  /[^.[\]]+|\[(?:(-?\d+(?:\.\d+)?)|(["'])((?:(?!\2)[^\\]|\\.)*?)\2)\]|(?=(?:\.|\[\])(?:\.|\[\]|$))/g;
const reEscapeChar = /\\(\\)?/g;

function stringToPath(s: string): string[] {
  const result: string[] = [];
  if (s.charCodeAt(0) === 46 /* '.' */) {
    result.push("");
  }
  s.replace(
    rePropName,
    (match: string, num?: string, quote?: string, sub?: string): string => {
      if (quote) {
        result.push((sub as string).replace(reEscapeChar, "$1"));
      } else {
        result.push(num || match);
      }
      return match;
    }
  );
  return result;
}

function isKey(value: string, obj: unknown): boolean {
  return (
    reIsPlainProp.test(value) ||
    !reIsDeepProp.test(value) ||
    (obj != null && value in Object(obj))
  );
}

export function solve(obj: unknown, path: string): unknown {
  if (obj == null) {
    return undefined;
  }

  const keys = isKey(path, obj) ? [path] : stringToPath(path);

  let cur: any = obj;
  let i = 0;
  while (cur != null && i < keys.length) {
    cur = cur[keys[i]];
    i++;
  }

  return i > 0 && i === keys.length ? cur : undefined;
}

