    K: 2, L: 4, M: 18, N: 20, O: 11, P: 3, Q: 6, R: 8, S: 12, T: 14,
    U: 16, V: 10, W: 22, X: 25, Y: 24, Z: 23,
  };
  const ODD_DIGIT = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const ch = s[i];
    const digitPos = isDigitPos(i);
    const dv = digitPos ? digitAt(ch) : -1;
    if (i % 2 === 0) {
      // 1st, 3rd, ... 15th characters: odd table
      sum += digitPos ? ODD_DIGIT[dv] : ODD[ch];
    } else {
      // 2nd, 4th, ... 14th characters: digit value or letter index
      sum += digitPos ? dv : ch.charCodeAt(0) - 65;
    }
  }

  const expected = String.fromCharCode(65 + (sum % 26));
  return expected === s[15];
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  if (!/^[A-Za-z0-9]{16}$/.test(code)) return false;
  const s = code.toUpperCase();

  const VOWELS = "AEIOU";
  const LETTER_DIGITS = "LMNPQRSTUV";
  const DIGIT_POS = [6, 7, 9, 10, 12, 13, 14];
  const ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  // Odd-position values, indexed by letter A..Z
  const ODD_VALUES = [
    1, 0, 5, 7, 9, 13, 15, 17, 19, 21, // A-J (also digits 0-9)
    2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23, // K-Z
  ];

  const isUpperLetter = (ch: string): boolean => /^[A-Z]$/.test(ch);

  // Name code: consonants, then vowels, then X padding
  const nameOk = (part: string): boolean => {
    let seenVowel = false;
    let seenX = false;
    for (const ch of part) {
      if (!isUpperLetter(ch)) return false;
      if (seenX) {
        if (ch !== "X") return false;
        continue;
      }
      if (ch === "X") {
        seenX = true;
        continue;
      }
      const isV = VOWELS.includes(ch);
      if (seenVowel) {
        if (!isV) return false;
      } else if (isV) {
        seenVowel = true;
      }
    }
    return true;
  };

  if (!nameOk(s.slice(0, 3)) || !nameOk(s.slice(3, 6))) return false;

  // Digit-holding positions: digit or letter LMNPQRSTUV standing for 0-9
  const digitValue = (ch: string): number => {
    if (ch >= "0" && ch <= "9") return ch.charCodeAt(0) - 48;
    return LETTER_DIGITS.indexOf(ch);
  };
  const vals: number[] = new Array(16).fill(-1);
  for (const i of DIGIT_POS) {
    const v = digitValue(s[i]);
    if (v < 0) return false;
    vals[i] = v;
  }

  // Year
  const year = vals[6] * 10 + vals[7];

  // Month
  const monthIdx = "ABCDEHLMPRST".indexOf(s[8]);
  if (monthIdx < 0) return false;
  const month = monthIdx + 1;

  // Day (female: +40)
  let day = vals[9] * 10 + vals[10];
  if (day > 40) day -= 40;
  const leap = year % 4 === 0; // 00 included
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) return false;

  // Place of birth: letter then 3 digit-holding characters
  if (!"ABCDEFGHILMZ".includes(s[11])) return false;

  // Check letter
  if (!isUpperLetter(s[15])) return false;

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const isDig = DIGIT_POS.includes(i);
    if (i % 2 === 0) {
      // 1st, 3rd, ... (odd positions in 1-based numbering)
      const letter = isDig ? ALPHA[vals[i]] : s[i];
      const idx = ALPHA.indexOf(letter);
      if (idx < 0) return false;
      sum += ODD_VALUES[idx];
    } else {
      // 2nd, 4th, ... (even positions in 1-based numbering)
      if (isDig) {
        sum += vals[i];
      } else {
        const idx = ALPHA.indexOf(s[i]);
        if (idx < 0) return false;
        sum += idx;
      }
    }
  }

  return ALPHA[sum % 26] === s[15];
}

