function isKey(value: string, obj: unknown): boolean {
  return (
    reIsPlainProp.test(value) ||
    !reIsDeepProp.test(value) ||
    (obj != null && value in Object(obj))
  );
}

export function solve(obj: unknown, path: string): unknown {
  const keys: string[] = isKey(path, obj) ? [path] : stringToPath(path);

  let cur: any = obj;
  let index = 0;
  while (cur != null && index < keys.length) {
    cur = cur[keys[index++]];
  }
  return index && index === keys.length ? cur : undefined;
}

